import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';
import { toast } from 'react-toastify';

export default function SellerProductReels() {
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [productName, setProductName] = useState('');
    const { productId } = useParams();
    const navigate = useNavigate();

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        loadProductReels();
    }, [productId]);

    const loadProductReels = async () => {
        try {
            setLoading(true);
            
            // Parse the product ID as integer
            const parsedProductId = parseInt(productId);
            
            // Get product name
            const productNamesResponse = await ApiService.getProductNamesByIds([parsedProductId]);
            if (productNamesResponse.success && productNamesResponse.data[parsedProductId]) {
                setProductName(productNamesResponse.data[parsedProductId]);
            } else {
                setProductName(`Product ${parsedProductId}`);
            }
            
            // Get seller reels from API
            const user = JSON.parse(localStorage.getItem('studioUser'));
            const vendorId = user?.vendor_id || 1;
            const response = await ApiService.getSellerReels(vendorId);
            
            if (response.success) {
                // Filter reels that contain this product ID
                // The product_ids field is an array of integers
                const filteredReels = response.data.filter(reel => {
                    if (reel.product_ids && Array.isArray(reel.product_ids)) {
                        return reel.product_ids.some(id => {
                            const reelProductId = parseInt(id);
                            return !isNaN(reelProductId) && reelProductId > 0 && reelProductId === parsedProductId;
                        });
                    }
                    return false;
                });
                
                setReels(filteredReels);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading product reels:', error);
            toast.error('Failed to load reels: ' + error.message);
            setLoading(false);
            
            // Fallback to sample data in case of error
            const parsedProductId = parseInt(productId);
            const productNamesResponse = await ApiService.getProductNamesByIds([parsedProductId]);
            let displayName = `Product ${parsedProductId}`;
            if (productNamesResponse.success && productNamesResponse.data[parsedProductId]) {
                displayName = productNamesResponse.data[parsedProductId];
            }
            setProductName(displayName);
            
            setTimeout(() => {
                const sampleReels = [
                    {
                        id: 1,
                        title: `${displayName} - Reel 1`,
                        video_url: "https://sample-videos.com/video123/mp4/720/big_buck_bunny_720p_1mb.mp4",
                        thumbnail_url: "",
                        status: "approved",
                        category_name: "Fashion",
                        created_at: "2023-06-15T10:30:00Z",
                        views: 1250,
                        likes: 342
                    },
                    {
                        id: 2,
                        title: `${displayName} - Reel 2`,
                        video_url: "https://sample-videos.com/video123/mp4/720/big_buck_bunny_720p_1mb.mp4",
                        thumbnail_url: "",
                        status: "approved",
                        category_name: "Fashion",
                        created_at: "2023-06-20T14:15:00Z",
                        views: 890,
                        likes: 124
                    }
                ];
                
                setReels(sampleReels);
                setLoading(false);
            }, 500);
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Function to render video player for a reel
    const renderVideoPlayer = (reel) => {
        // For testing purposes, we'll use the direct video URL
        const fullVideoUrl = reel.video_url;
        
        if (!fullVideoUrl) {
            return <div className="alert alert-warning">No video available for this reel</div>;
        }
        
        return (
            <div className="video-player-container mb-4">
                <video 
                    width="100%" 
                    height="auto" 
                    controls
                    poster={reel.thumbnail_url || ''}
                >
                    <source src={fullVideoUrl} type="video/mp4" />
                    Your browser does not support the video tag.
                </video>
                <div className="mt-2">
                    <h5>{reel.title}</h5>
                    <p className="text-muted">
                        Status: {getStatusBadge(reel.status)} | 
                        Category: {reel.category_name || 'N/A'} | 
                        Date: {new Date(reel.created_at).toLocaleDateString()} |
                        Views: {reel.views || 0} | 
                        Likes: {reel.likes || 0}
                    </p>
                </div>
            </div>
        );
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Reels for {productName}</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Product Reels</h5>
                        <button 
                            className="btn btn-secondary" 
                            onClick={() => navigate(-1)}
                        >
                            <i className="ri-arrow-left-line me-1"></i> Back
                        </button>
                    </div>
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found for this product</h5>
                                <p className="text-muted">There are no reels associated with {productName}.</p>
                                <button 
                                    className="btn btn-primary" 
                                    onClick={() => navigate(-1)}
                                >
                                    <i className="ri-arrow-left-line me-1"></i> Back to All Reels
                                </button>
                            </div>
                        ) : (
                            <div>
                                {/* Display videos directly instead of list */}
                                {reels.map((reel) => (
                                    <div key={reel.id} className="mb-4">
                                        {renderVideoPlayer(reel)}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
